const topic=(title:string,simple:string,why:string,mechanism:string,technical:string,experiment:string,source:string,code:string|undefined,steps:string[],remember:string):Topic=>({title,simple,why,mechanism,technical,experiment,source,code,steps,remember});
const dirs=['07_RTOS','08_UART_And_Python_Host','09_Sensors_And_Buses','10_Fixed_Point_And_DMA','11_Faults_Watchdog_Power','12_Game'];
